//! Weights of the push-or-fold model ([`crate::pushfold::predict`]). Generated by
//! `experiments/stage/fit_pushfold.py`; do not edit. This is the placeholder
//! before the fit: it predicts a constant +1 (always push), so the bot
//! `stage-fold-learned` plays like `stage` until the script writes the fit.

use crate::pushfold::FEATURES;

/// Units per hidden layer.
pub const HIDDEN: usize = 1;
/// Input means and standard deviations (inputs are standardised first).
pub const MEAN: [f64; FEATURES] = [0.0; FEATURES];
pub const SD: [f64; FEATURES] = [1.0; FEATURES];
pub const W1: [[f64; FEATURES]; HIDDEN] = [[0.0; FEATURES]; HIDDEN];
pub const B1: [f64; HIDDEN] = [0.0; HIDDEN];
pub const W2: [[f64; HIDDEN]; HIDDEN] = [[0.0; HIDDEN]; HIDDEN];
pub const B2: [f64; HIDDEN] = [0.0; HIDDEN];
pub const W3: [f64; HIDDEN] = [0.0; HIDDEN];
/// Linear skip from the standardised inputs.
pub const LIN: [f64; FEATURES] = [0.0; FEATURES];
pub const B3: f64 = 1.0;
/// Held-out rows and the script's predictions, for the parity test.
pub const CHECK: &[([f64; FEATURES], f64)] = &[];
